import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"外掛","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/plugins.md","filePath":"zh-TW/user-guide/settings/plugins.md","lastUpdated":1785467127000}'),n={name:"zh-TW/user-guide/settings/plugins.md"};function o(i,t,p,g,l,d){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="外掛" tabindex="-1">外掛 <a class="header-anchor" href="#外掛" aria-label="Permalink to &quot;外掛&quot;">​</a></h1><p>列出所有已安裝的外掛，頁面頂部的徽章會顯示目前載入的 Plugin SDK 版本(如果要對照<a href="./../../dev-guide/">開發手冊</a>開發外掛，這個版本號很有用)。</p><h2 id="每個外掛的卡片" tabindex="-1">每個外掛的卡片 <a class="header-anchor" href="#每個外掛的卡片" aria-label="Permalink to &quot;每個外掛的卡片&quot;">​</a></h2><p>每個已安裝的外掛都有一張卡片，顯示圖示、名稱、版本號、DLL 檔案名稱以及外掛的<strong>整體功能簡介</strong>。</p><p>點擊卡片可以展開，檢視它註冊的功能元件，按類型分組（搜尋來源、動態選單提供者等）——每個可切換的元件都有自己的<strong>啟用/停用核取方塊</strong>；標記為必要項目的元件會顯示一個鎖形圖示，不能關閉。將滑鼠停留在各元件上時，會彈出該元件的<strong>詳細功能說明 ToolTip</strong>。</p><p>當某個分組（或整個外掛）有 2 個及以上可切換元件時，標題旁會出現一個<strong>全選/全不選</strong>連結，點擊即可一次性切換該範圍內的所有核取方塊，不用逐個手動勾選。</p><p>如果外掛公開了自己的設定項(超出簡單啟用/停用的範疇)，卡片頂部會出現一個<strong>設定</strong>按鈕，點擊會開啟該外掛自己的設定對話方塊。</p><p>頁面底部有一條提示橫幅，說明部分元件的開關改動需要重新啟動 SwiftList 才能生效。</p><p>如果沒有安裝任何外掛，頁面會顯示一個空狀態提示。</p><p>想看外掛自己的<strong>設定</strong>對話方塊實際長什麼樣、能改什麼(比如改一個觸發關鍵字)，可以參考<a href="./../instant-answers.html">即時答案與關鍵字功能</a>。</p>',10)])])}const h=e(n,[["render",o]]);export{_ as __pageData,h as default};
